4	import { canonicalJson, digestOf, sha256Text, assertDigest } from './canonical.js';
5	import { ConflictError, NotFoundError, ValidationError } from './errors.js';
6	import { commandSources, executeArtifact, normalizeCommand } from './executor.js';
7	import {
8	  actionIdOf,
9	  actionKey,
10	  assertHash,
11	  assertName,
12	  normalizeCacheInputs,
13	  normalizeEnv,
14	  normalizeInputs,
15	  normalizePath,
16	  runKey,
17	  KEY_SCHEMA,
18	} from './key.js';
19	import { ObjectStore } from './store.js';
20	
21	export const MANIFEST_SCHEMA = 'cachelattice/manifest/v1';
22	export const RUN_SCHEMA = 'cachelattice/run/v1';
23	const STATS_SCHEMA = 'cachelattice/stats/v1';
24	
25	const GRAPH_FIELDS = ['id', 'nodes', 'concurrency', 'limits'];
26	const NODE_FIELDS = ['id', 'action', 'needs', 'resources'];
27	const ACTION_FIELDS = ['name', 'command', 'inputs', 'env', 'depends_on'];
28	const INPUT_FIELDS = ['kind', 'path', 'digest'];
29	const CACHE_ENTRY_FIELDS = ['action_id', 'command', 'inputs', 'env', 'depends_on'];
30	
31	const HEX_KEY = /^[0-9a-f]{64}$/;
32	const ZERO_DIGEST = `sha256:${'0'.repeat(64)}`;
33	const RESOURCE_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,31}$/;
34	const RESOURCE_MAX = 1000000;
35	
36	function rejectUnknown(object, allowed, label) {
37	  for (const key of Object.keys(object)) {
38	    if (!allowed.includes(key)) {
39	      throw new ValidationError(`${label} contains an unknown field: ${key}`);
40	    }
41	  }
42	}
43	
44	function isPlainObject(value) {
45	  return value !== null && typeof value === 'object' && !Array.isArray(value);
46	}
47	
48	function normalizeProducers(value, label) {
49	  if (!Array.isArray(value)) throw new ValidationError(`${label} depends_on must be an array of action names`);
50	  const names = value.map((name) => assertName(name, `${label} dependency`));
51	  if (new Set(names).size !== names.length) {
52	    throw new ValidationError(`${label} lists a dependency twice`);
53	  }
54	  return [...names].sort();
55	}
56	
57	// Resource declarations are scheduling hints only: they gate when a node may
58	// start, never what it computes, so they live outside every key, manifest and
59	// artifact. Both limits and resources are plain objects from a resource name to
60	// a non-negative integer amount.
61	function normalizeResourceMap(value, label, minimum) {
62	  if (!isPlainObject(value)) throw new ValidationError(`${label} must be a plain object`);
63	  const normalized = {};
64	  for (const [name, amount] of Object.entries(value)) {
65	    if (!RESOURCE_NAME.test(name)) {
66	      throw new ValidationError(
67	        `resource name must match [A-Za-z][A-Za-z0-9_-]{0,31}, received ${JSON.stringify(name)}`,
68	      );
69	    }
70	    if (!Number.isInteger(amount) || amount < minimum || amount > RESOURCE_MAX) {
71	      throw new ValidationError(`${label} ${name} must be an integer between ${minimum} and ${RESOURCE_MAX}`);
72	    }
73	    normalized[name] = amount;
74	  }
75	  return normalized;
76	}
77	
78	export function assertCacheKey(value) {
79	  if (typeof value !== 'string' || !HEX_KEY.test(value)) {
80	    throw new ValidationError(
81	      `cache key must be 64 lowercase hex characters, received ${JSON.stringify(value)}`,
82	    );
83	  }
84	  return value;
85	}
86	
87	// A node key is only salted when there is something to fold in, which keeps the
88	// root node key of a graph exactly equal to the action key it runs.
89	export function nodeKeyOf(actionKey, upstreamKeys) {
90	  if (upstreamKeys.length === 0) return actionKey;
91	  return sha256Text(
92	    `cachelattice/node-key/v1\n${actionKey}\n${[...upstreamKeys].sort().join('\n')}`,
93	  );
94	}
95	
96	export function dependencyRunKey(dependencies) {
97	  const lines = dependencies
98	    .map((dependency) => `${dependency.action_id}:${dependency.key}`)
99	    .join('\n');
100	  return sha256Text(`cachelattice/dependency-run/v1\n${lines}`);
101	}
102	
103	// A miss and a hit must produce byte-identical manifests as well as
104	// byte-identical artifacts, so the manifest is derived purely from the action
105	// definition, the resolved dependency keys, and the artifact bytes. It carries
106	// no wall-clock timestamp, no node id, and no hint about whether it was
107	// recomputed or read back.
108	export function buildManifest({ actionId, key, command, inputs, env, dependencies, digest, size }) {
109	  return {
110	    schema: MANIFEST_SCHEMA,
111	    key_schema: KEY_SCHEMA,
112	    action_id: actionId,
113	    key,
114	    command,
115	    inputs,
116	    env,
117	    dependency_run_key: dependencyRunKey(dependencies),
118	    dependencies,
119	    digest: `sha256:${digest}`,
120	    size,
121	  };
122	}
123	
124	// Deterministic synthetic execution cost, so a graph run has the same shape on
125	// every machine and concurrency is observable without a real toolchain.
126	function syntheticDelay(command) {
127	  return 10 + (parseInt(sha256Text(canonicalJson(command)).slice(0, 4), 16) % 40);
128	}
129	
130	const sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds));
