132	export class Cachelattice {
133	  constructor({ dataDirectory, workspace, ambientEnv = process.env, clock = () => new Date() }) {
134	    this.store = new ObjectStore(dataDirectory);
135	    this.workspace = path.resolve(workspace);
136	    this.ambientEnv = ambientEnv;
137	    this.clock = clock;
138	    this.actions = new Map();
139	    this.graphs = new Map();
140	    this.runs = new Map();
141	    this.statsCache = null;
142	    this.loading = this.load();
143	  }
144	
145	  async load() {
146	    for (const entry of await this.readRegistry('actions')) this.actions.set(entry.name, entry);
147	    for (const entry of await this.readRegistry('graphs')) {
148	      // Graphs persisted before resource limits existed carry no declarations.
149	      entry.limits ??= {};
150	      for (const node of entry.nodes) node.resources ??= {};
151	      this.graphs.set(entry.id, entry);
152	    }
153	    for (const entry of await this.readRegistry('runs')) this.runs.set(entry.graph_id, entry);
154	    this.statsCache = (await this.store.readMeta('stats.json')) ?? this.blankStats();
155	  }
156	
157	  async readRegistry(kind) {
158	    const index = (await this.store.readMeta(`index/${kind}.json`)) ?? { items: [] };
159	    const items = [];
160	    for (const id of index.items) {
161	      const entry = await this.store.readMeta(`${kind}/${id}.json`);
162	      if (entry) items.push(entry);
163	    }
164	    return items;
165	  }
166	
167	  async writeRegistry(kind, id, entry) {
168	    await this.store.writeMeta(`${kind}/${id}.json`, entry);
169	    const index = (await this.store.readMeta(`index/${kind}.json`)) ?? { items: [] };
170	    if (!index.items.includes(id)) {
171	      await this.store.writeMeta(`index/${kind}.json`, { items: [...index.items, id].sort() });
172	    }
173	    return entry;
174	  }
175	
176	  blankStats() {
177	    return {
178	      schema: STATS_SCHEMA,
179	      actions_registered: 0,
180	      graphs_registered: 0,
181	      graph_runs: 0,
182	      nodes_scheduled: 0,
183	      cache_hits: 0,
184	      cache_misses: 0,
185	      artifacts_executed: 0,
186	      cache_writes: 0,
187	      remote_reads: 0,
188	      remote_writes: 0,
189	      cache_entries: 0,
190	    };
191	  }
192	
193	  async stats() {
194	    await this.loading;
195	    this.statsCache.cache_entries = (await this.store.listKeys(100000)).length;
196	    return { ...this.statsCache };
197	  }
198	
199	  bump(field, amount = 1) {
200	    this.statsCache[field] += amount;
201	  }
202	  async persistStats() {
203	    await this.store.writeMeta('stats.json', this.statsCache);
204	  }
205	
206	  actionView(action) {
207	    return {
208	      name: action.name,
209	      action_id: action.action_id,
210	      key: action.key,
211	      command: action.command,
212	      inputs: action.inputs,
213	      env: action.env.names,
214	      env_values: action.env.values,
215	      depends_on: action.depends_on,
216	    };
217	  }
218	
219	  graphView(graph) {
220	    return { id: graph.id, concurrency: graph.concurrency, limits: graph.limits, nodes: graph.nodes };
221	  }
222	
223	  // ---------------------------------------------------------------- actions
224	
225	  // Validates the declared input list and resolves each entry to the digest that
226	  // enters the key. File inputs are snapshotted here, at registration time, so an
227	  // action key stays stable when the workspace changes underneath it.
228	  async resolveInputs(declaredInputs) {
229	    if (!Array.isArray(declaredInputs) || declaredInputs.length === 0) {
230	      throw new ValidationError('action inputs must be a non-empty array');
231	    }
232	    const declared = normalizeInputs(
233	      declaredInputs.map((input) => {
234	        if (!isPlainObject(input)) throw new ValidationError('each input must be an object');
235	        rejectUnknown(input, INPUT_FIELDS, 'input');
236	        if (input.kind !== 'file' && input.kind !== 'hash') {
237	          throw new ValidationError('input kind must be "file" or "hash"');
238	        }
239	        if (input.kind === 'file' && 'digest' in input) {
240	          throw new ValidationError('a file input must not carry a digest; the service hashes it');
241	        }
242	        if (input.kind === 'hash' && !('digest' in input)) {
243	          throw new ValidationError('a hash input must carry a digest');
244	        }
245	        // normalizeInputs only sorts and de-duplicates; the real digest replaces
246	        // this placeholder below.
247	        return input.kind === 'file' ? { kind: 'file', path: input.path, digest: ZERO_DIGEST } : input;
248	      }),
249	    );
250	    const resolved = [];
251	    for (const input of declared) {
252	      resolved.push(
253	        input.kind === 'hash'
254	          ? { kind: 'hash', path: input.path, digest: assertHash(input.digest, 'input hash') }
255	          : { kind: 'file', path: input.path, digest: digestOf(await readWorkspaceFile(this.workspace, input.path)) },
256	      );
257	    }
258	    return resolved;
259	  }
260	
261	  async putAction(body, { refresh = false } = {}) {
262	    await this.loading;
263	    if (!isPlainObject(body)) throw new ValidationError('request body must be a JSON object');
264	    rejectUnknown(body, ACTION_FIELDS, 'action');
265	    const name = assertName(body.name, 'action name');
266	    if (!isPlainObject(body.command)) throw new ValidationError('action command must be an object');
267	    if (!Array.isArray(body.env)) throw new ValidationError('action env must be an array of names');
268	    const inputs = await this.resolveInputs(body.inputs);
269	
270	    const command = normalizeCommand(body.command);
271	    for (const source of commandSources(command)) {
272	      const normalized = normalizePath(source, 'command source');
273	      if (!inputs.some((input) => input.path === normalized)) {
274	        throw new ValidationError(`command reads ${normalized}, which is not a declared input`);
275	      }
276	    }
277	    if (command.kind === 'concat-text' && command.sources.length === 0) {
278	      throw new ValidationError('command sources must not be empty');
279	    }
280	
281	    // A declared producer must exist and must have produced one of the hash
282	    // inputs. This keeps the causal chain honest: a consumer's key can only move
283	    // for a producer whose artifact it actually consumes.
284	    const dependsOn = normalizeProducers(body.depends_on ?? [], `action ${name}`);
285	    for (const producerName of dependsOn) {
286	      const producer = this.actions.get(producerName);
287	      if (!producer) throw new ValidationError(`action ${name} depends on unregistered action ${producerName}`);
288	      if (!inputs.some((input) => input.kind === 'hash' && input.digest === producer.key)) {
289	        throw new ValidationError(
290	          `action ${name} depends on ${producerName} but does not declare its artifact as a hash input`,
291	        );
292	      }
293	    }
294	    const env = normalizeEnv(body.env, this.ambientEnv);
295	    const entry = {
296	      name,
297	      action_id: actionIdOf(name),
298	      command,
299	      inputs,
300	      env,
301	      // The artifact of every producer named here must be declared as a hash
302	      // input, and the graph must wire exactly these producers as `needs`. The
303	      // producer *keys* are folded into the node key at run time (see plan()),
304	      // which is what makes an upstream change invalidate everything below it.
305	      depends_on: dependsOn,
306	    };
307	    entry.key = actionKey({ command: entry.command, inputs, env });
308	
309	    // A name identifies one action. Registering it again is a conflict no matter
310	    // how similar the definition is, so that replacing an action is always the
311	    // explicit, reviewable act of a PUT.
312	    const previous = this.actions.get(name);
313	    if (previous && !refresh) {
314	      throw new ConflictError(
315	        `action ${name} is already registered; PUT /actions/${name} to replace it`,
316	      );
317	    }
318	    this.actions.set(name, entry);
319	    if (!previous) this.bump('actions_registered');
320	    await this.writeRegistry('actions', name, entry);
321	    await this.persistStats();
322	    return this.actionView(entry);
323	  }
324	
325	  async getAction(name) {
326	    await this.loading;
327	    const entry = this.actions.get(name);
328	    if (!entry) throw new NotFoundError(`action ${name} is not registered`);
329	    return this.actionView(entry);
330	  }
331	
332	  async listActions() {
333	    await this.loading;
334	    return [...this.actions.values()]
335	      .map((action) => this.actionView(action))
336	      .sort((left, right) => (left.name < right.name ? -1 : left.name > right.name ? 1 : 0));
337	  }
338	
339	  // ---------------------------------------------------------------- graphs
340	
341	  async putGraph(graphId, body) {
342	    await this.loading;
343	    const id = assertName(graphId, 'graph id');
344	    if (!isPlainObject(body)) throw new ValidationError('request body must be a JSON object');
345	    rejectUnknown(body, GRAPH_FIELDS, 'graph');
346	    if (body.id !== undefined && body.id !== id) {
347	      throw new ValidationError('graph body id must match the path id');
348	    }
349	    if (!Array.isArray(body.nodes) || body.nodes.length === 0) {
350	      throw new ValidationError('graph nodes must be a non-empty array');
351	    }
352	    const concurrency = body.concurrency === undefined ? 1 : body.concurrency;
353	    if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 64) {
354	      throw new ValidationError('graph concurrency must be an integer between 1 and 64');
355	    }
356	    const limits = normalizeResourceMap(body.limits === undefined ? {} : body.limits, 'graph limits', 1);
357	
358	    const nodes = body.nodes.map((node) => {
359	      if (!isPlainObject(node)) throw new ValidationError('each graph node must be an object');
360	      rejectUnknown(node, NODE_FIELDS, 'graph node');
361	      const nodeId = assertName(node.id, 'node id');
362	      const action = assertName(node.action, 'node action');
363	      const needs = node.needs === undefined ? [] : node.needs;
364	      if (!Array.isArray(needs)) throw new ValidationError(`node ${nodeId} needs must be an array`);
365	      if (new Set(needs).size !== needs.length) {
366	        throw new ValidationError(`node ${nodeId} lists a dependency twice`);
367	      }
368	      for (const dependency of needs) assertName(dependency, `node ${nodeId} dependency`);
369	      const resources = normalizeResourceMap(
370	        node.resources === undefined ? {} : node.resources,
371	        `node ${nodeId} resources`,
372	        0,
373	      );
374	      // Every reserved resource must be backed by a graph-level quota, and one
375	      // node may never ask for more than the whole graph allows.
376	      for (const [name, amount] of Object.entries(resources)) {
377	        if (!(name in limits)) {
378	          throw new ValidationError(`node ${nodeId} reserves resource ${name}, which has no graph limit`);
379	        }
380	        if (amount > limits[name]) {
381	          throw new ValidationError(
382	            `node ${nodeId} reserves ${amount} of ${name}, over the graph limit of ${limits[name]}`,
383	          );
384	        }
385	      }
386	      return { id: nodeId, action, needs: [...needs].sort(), resources };
387	    });
388	
389	    const seen = new Set();
390	    for (const node of nodes) {
391	      if (seen.has(node.id)) throw new ValidationError(`duplicate node id: ${node.id}`);
392	      for (const dependency of node.needs) {
393	        if (dependency === node.id) throw new ValidationError(`node ${node.id} needs itself`);
394	        if (!seen.has(dependency)) {
395	          throw new ValidationError(
396	            `node ${node.id} needs ${dependency}, which is not defined earlier in the graph; a dependency cycle is not allowed`,
397	          );
398	        }
399	      }
400	      if (!this.actions.has(node.action)) {
401	        throw new ValidationError(`node ${node.id} references unregistered action ${node.action}`);
402	      }
403	      seen.add(node.id);
404	    }
405	
406	    const entry = { id, concurrency, limits, nodes };
407	    const existed = this.graphs.has(id);
408	    this.graphs.set(id, entry);
409	    if (!existed) this.bump('graphs_registered');
410	    await this.writeRegistry('graphs', id, entry);
411	    await this.persistStats();
412	    return this.graphView(entry);
413	  }
414	
415	  async getGraph(graphId) {
416	    await this.loading;
417	    const graph = this.graphs.get(graphId);
418	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
419	    const lastRun = this.runs.get(graphId) ?? null;
420	    return {
421	      ...this.graphView(graph),
422	      last_run: lastRun
423	        ? {
424	            run_key: lastRun.run_key,
425	            completed_at: lastRun.completed_at,
426	            duration_ms: lastRun.duration_ms,
427	            peak_parallel: lastRun.peak_parallel,
428	            cache_hits: lastRun.cache_hits,
429	            cache_misses: lastRun.cache_misses,
430	            nodes: lastRun.nodes.map((node) => ({
431	              id: node.id,
432	              action: node.action,
433	              key: node.key,
434	              digest: node.digest,
435	              cache: node.cache,
436	            })),
437	          }
438	        : null,
439	    };
440	  }
441	
442	  async listGraphs() {
443	    await this.loading;
444	    return [...this.graphs.values()]
445	      .map((graph) => this.graphView(graph))
446	      .sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
447	  }
448	
449	  // --------------------------------------------------------------- planning
450	
451	  // Resolves every node to a concrete action key. A node's key folds in the keys
452	  // of every action it needs, so a change anywhere upstream moves every key
453	  // downstream of it.
454	  plan(graphId) {
455	    const graph = this.graphs.get(graphId);
456	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
457	    const byId = new Map(graph.nodes.map((node) => [node.id, node]));
458	    const planned = new Map();
459	
460	    const visit = (nodeId, trail) => {
461	      const known = planned.get(nodeId);
462	      if (known) return known;
463	      if (trail.has(nodeId)) {
464	        throw new ConflictError(`graph ${graphId} contains a dependency cycle through ${nodeId}`);
465	      }
466	      trail.add(nodeId);
467	      const node = byId.get(nodeId);
468	      if (!node) throw new ValidationError(`graph ${graphId} has no node ${nodeId}`);
469	      const action = this.actions.get(node.action);
470	      if (!action) {
471	        throw new ConflictError(`node ${nodeId} references action ${node.action}, which no longer exists`);
472	      }
473	      const upstream = node.needs.map((needed) => visit(needed, trail));
474	      const produced = upstream.map((entry) => entry.action.name).sort();
475	      const declared = action.depends_on;
476	      if (produced.join('\n') !== declared.join('\n')) {
477	        throw new ConflictError(
478	          `node ${nodeId} is wired to [${produced.join(', ')}] but action ${action.name} declares ` +
479	            `depends_on [${declared.join(', ')}]; re-register the action or rewire the graph`,
480	        );
481	      }
482	      const key = nodeKeyOf(action.key, upstream.map((entry) => entry.key));
483	      trail.delete(nodeId);
484	      const resolved = {
485	        node,
486	        action,
487	        key,
488	        dependencies: upstream
489	          .map((entry) => ({ action_id: entry.action.name, key: entry.key }))
490	          .sort((left, right) =>
491	            left.action_id < right.action_id ? -1 : left.action_id > right.action_id ? 1 : 0,
492	          ),
493	      };
494	      planned.set(nodeId, resolved);
495	      return resolved;
496	    };
497	
498	    for (const node of graph.nodes) visit(node.id, new Set());
499	    return planned;
500	  }
501	
502	  // -------------------------------------------------------------- execution
503	
504	  async runGraph(graphId, { useCache = true } = {}) {
505	    await this.loading;
506	    const graph = this.graphs.get(graphId);
507	    if (!graph) throw new NotFoundError(`graph ${graphId} is not registered`);
508	    const planned = this.plan(graphId);
509	    const key = runKey(
510	      graph.nodes.map((node) => ({ action_id: planned.get(node.id).action.name, key: planned.get(node.id).key })),
511	    );
512	
513	    // A run is always scheduled; there is no whole-run fast path, because the
514	    // answer to "was this a cache hit?" must come from the store on every run.
515	    // `plan_reused` only reports that no key moved since the previous run.
516	    const previous = this.runs.get(graphId) ?? null;
517	    const stale = graph.nodes.flatMap((node) => {
518	      const before = previous?.nodes.find((candidate) => candidate.id === node.id);
519	      const action = planned.get(node.id);
520	      return before && before.key !== action.key
521	        ? [{ id: node.id, action: action.action.name, was: before.key, now: action.key }]
522	        : [];
523	    });
524	    const planReused = previous !== null && previous.run_key === key;
525	
526	    const state = new Map(graph.nodes.map((node) => [node.id, { node, status: 'pending' }]));
527	    const isReady = (id) =>
528	      state.get(id).status === 'pending' &&
529	      state.get(id).node.needs.every((needed) => state.get(needed).status === 'done');
530	    const readyIds = () => graph.nodes.map((node) => node.id).filter(isReady).sort();
531	
532	    let hits = 0;
533	    let misses = 0;
534	    let inFlight = 0;
535	    let peakParallel = 0;
536	    const startedAt = Date.now();
537	    this.bump('graph_runs');
538	    this.bump('nodes_scheduled', graph.nodes.length);
539	
540	    // Resource bookkeeping for this run only; quotas never leak across graphs.
541	    // `reserved` is what running nodes currently hold, `peak` the high-water
542	    // mark, with every declared limit present from the start so an unused
543	    // resource reports a peak of 0.
544	    const reserved = {};
545	    const peakResources = {};
546	    for (const name of Object.keys(graph.limits)) {
547	      reserved[name] = 0;
548	      peakResources[name] = 0;
549	    }
550	    const fits = (resources) =>
551	      Object.entries(resources).every(([name, amount]) => reserved[name] + amount <= graph.limits[name]);
552	    const reserve = (resources) => {
553	      for (const [name, amount] of Object.entries(resources)) {
554	        reserved[name] += amount;
555	        peakResources[name] = Math.max(peakResources[name], reserved[name]);
556	      }
557	    };
558	    const release = (resources) => {
559	      for (const [name, amount] of Object.entries(resources)) reserved[name] -= amount;
560	    };
561	
562	    const results = [];
563	    while (results.length < graph.nodes.length) {
564	      // Deterministic dispatch order: lexicographic by node id. A candidate
565	      // starts only when the concurrency budget and every resource it reserves
566	      // fit; one that does not fit is skipped for now, so a resource-hungry
567	      // candidate never blocks later ready nodes. Concurrency remains the only
568	      // source of timing freedom and never changes an artifact.
569	      for (const id of readyIds()) {
570	        if (inFlight >= graph.concurrency) break;
571	        const entry = state.get(id);
572	        if (!fits(entry.node.resources)) continue;
573	        entry.status = 'running';
574	        reserve(entry.node.resources);
575	        inFlight += 1;
576	        peakParallel = Math.max(peakParallel, inFlight);
577	        const dependencies = entry.node.needs.map((needed) => {
578	          const produced = state.get(needed).result;
579	          return { action_id: produced.action_id, key: produced.key };
580	        });
581	        entry.promise = this.executeNode(planned.get(entry.node.id), dependencies, { useCache })
582	          .then((outcome) => {
583	            entry.status = 'done';
584	            entry.result = outcome;
585	            results.push(outcome);
586	            if (outcome.cache === 'hit') hits += 1;
587	            else misses += 1;
588	          })
589	          .catch((error) => {
590	            entry.status = 'failed';
591	            entry.error = error;
592	          })
593	          .finally(() => {
594	            release(entry.node.resources);
595	            inFlight -= 1;
596	          });
597	      }
598	      const running = [...state.values()].filter((entry) => entry.status === 'running');
599	      if (running.length === 0) {
600	        // A failed node must surface as a failed request, never as a hang.
601	        const failed = [...state.values()].find((entry) => entry.status === 'failed');
602	        if (failed) throw failed.error;
603	        if (results.length < graph.nodes.length) {
604	          throw new ConflictError(`graph ${graphId} has no schedulable node; check its dependencies`);
605	        }
606	        break;
607	      }
608	      await Promise.all(running.map((entry) => entry.promise));
609	    }
610	
611	    const nodes = results
612	      .map((result) => ({
613	        id: result.id,
614	        action: result.action_id,
615	        key: result.key,
616	        digest: result.digest,
617	        size: result.size,
618	        cache: result.cache,
619	        dependencies: result.dependencies,
620	        resources: { ...result.resources },
621	      }))
622	      .sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
623	
624	    const record = {
625	      schema: RUN_SCHEMA,
626	      graph_id: graphId,
627	      run_key: key,
628	      completed_at: this.clock().toISOString(),
629	      concurrency: graph.concurrency,
630	      duration_ms: Date.now() - startedAt,
631	      peak_parallel: peakParallel,
632	      plan_reused: planReused,
633	      cache_hits: hits,
634	      cache_misses: misses,
635	      stale_nodes: stale,
636	      resource_limits: { ...graph.limits },
637	      peak_resources: { ...peakResources },
638	      nodes,
639	    };
640	    this.runs.set(graphId, record);
641	    await this.writeRegistry('runs', graphId, record);
642	    this.bump('cache_hits', hits);
643	    this.bump('cache_misses', misses);
644	    await this.persistStats();
645	
646	    return {
647	      graph_id: graphId,
648	      run_key: key,
649	      plan_reused: planReused,
650	      cache_hits: hits,
651	      cache_misses: misses,
652	      peak_parallel: peakParallel,
653	      resource_limits: { ...graph.limits },
654	      peak_resources: { ...peakResources },
655	      stale_nodes: stale,
656	      nodes,
657	    };
658	  }
659	
660	  async executeNode(planned, dependencies, { useCache }) {
661	    const { node, action, key } = planned;
662	    if (useCache && this.store.hasManifest(key)) {
663	      const { manifest } = await this.store.readArtifact(key);
664	      this.assertManifestMatches(manifest, action, key);
665	      return {
666	        id: node.id,
667	        action_id: action.name,
668	        key,
669	        digest: manifest.digest,
670	        size: manifest.size,
671	        cache: 'hit',
672	        dependencies,
673	        resources: node.resources,
674	      };
675	    }
676	
677	    await sleep(syntheticDelay(action.command));
678	    const buffer = await executeArtifact({
679	      command: action.command,
680	      inputs: action.inputs,
681	      env: action.env,
682	      dependencies,
683	      workspace: this.workspace,
684	    });
685	    const digest = await this.store.writeBlob(buffer);
686	    const manifest = buildManifest({
687	      actionId: action.name,
688	      key,
689	      command: action.command,
690	      inputs: action.inputs,
691	      env: action.env,
692	      dependencies,
693	      digest,
694	      size: buffer.length,
695	    });
696	    // A concurrent miss for the same key may have won the race. The manifests
697	    // are identical by construction, so the winner is irrelevant; the blob is
698	    // content-addressed, so there is only ever one possibility.
699	    if (!this.store.hasManifest(key)) await this.store.writeManifest(key, manifest);
700	    this.bump('artifacts_executed');
701	    this.bump('cache_writes');
702	    return {
703	      id: node.id,
704	      action_id: action.name,
705	      key,
706	      digest: manifest.digest,
707	      size: manifest.size,
708	      cache: 'miss',
709	      dependencies,
710	      resources: node.resources,
711	    };
712	  }
713	
714	  // ---------------------------------------------------------------- verify
715	
716	  // Re-executes the graph with cache reads disabled and compares every node with
717	  // what the cache already holds, by digest and byte by byte. A cache entry that
718	  // cannot even be read back (missing blob, tampered bytes) is reported as an
719	  // issue rather than raised, because that is exactly what verification is for.
720	  async verifyGraph(graphId) {
721	    await this.loading;
722	    const baseline = this.runs.get(graphId);
723	    if (!baseline) throw new NotFoundError(`graph ${graphId} has no completed run to verify`);
724	    const cached = new Map();
725	    const issues = [];
726	    for (const node of baseline.nodes) {
727	      try {
728	        const entry = await this.store.readArtifact(node.key);
729	        cached.set(node.id, { digest: node.digest, buffer: entry.buffer });
730	      } catch (error) {
731	        issues.push({ id: node.id, issue: 'cache_unreadable', detail: error.message });
732	      }
733	    }
734	    const rerun = await this.runGraph(graphId, { useCache: false });
735	    let byteIdentical = 0;
736	    for (const node of rerun.nodes) {
737	      const before = cached.get(node.id);
738	      if (!before) {
739	        if (!issues.some((issue) => issue.id === node.id)) {
740	          issues.push({ id: node.id, issue: 'missing_from_baseline' });
741	        }
742	        continue;
743	      }
744	      if (before.digest !== node.digest) {
745	        issues.push({ id: node.id, issue: 'digest_changed', cached: before.digest, recomputed: node.digest });
746	        continue;
747	      }
748	      let after;
749	      try {
750	        after = await this.store.readArtifact(node.key);
751	      } catch (error) {
752	        issues.push({ id: node.id, issue: 'cache_unreadable', detail: error.message });
753	        continue;
754	      }
755	      if (before.buffer.equals(after.buffer)) byteIdentical += 1;
756	      else issues.push({ id: node.id, issue: 'bytes_differ', digest: node.digest });
757	    }
758	    return {
759	      graph_id: graphId,
760	      run_key: rerun.run_key,
761	      identical: issues.length === 0,
762	      comparisons: rerun.nodes.length,
763	      byte_identical: byteIdentical,
764	      issues,
765	    };
766	  }
767	
768	  // ----------------------------------------------------------------- cache
769	
770	  async cacheGet(key) {
771	    await this.loading;
772	    const normalized = assertCacheKey(key);
773	    const { manifest, buffer } = await this.store.readArtifact(normalized);
774	    return { manifest, buffer };
775	  }
776	
777	  // Ingest an action manifest. Any peer that knows a cached action key may push
778	  // the entry, and it is accepted only when every hashed field in the manifest
779	  // still recomputes to the key being claimed.
780	  async cachePut(key, entry, buffer) {
781	    await this.loading;
782	    const normalized = assertCacheKey(key);
783	    if (!isPlainObject(entry)) throw new ValidationError('cache entry must be a JSON object');
784	    rejectUnknown(entry, CACHE_ENTRY_FIELDS, 'cache entry');
785	    if (!isPlainObject(entry.command)) throw new ValidationError('cache entry command must be an object');
786	    if (!Array.isArray(entry.inputs) || !Array.isArray(entry.env)) {
787	      throw new ValidationError('cache entry inputs and env must be arrays');
788	    }
789	    for (const input of entry.inputs) {
790	      if (!isPlainObject(input)) throw new ValidationError('cache entry inputs must be objects');
791	      rejectUnknown(input, INPUT_FIELDS, 'cache entry input');
792	      if (input.kind !== 'file' && input.kind !== 'hash') {
793	        throw new ValidationError('cache entry input kind must be "file" or "hash"');
794	      }
795	    }
796	    const command = normalizeCommand(entry.command);
797	    const inputsValue = normalizeCacheInputs(entry.inputs);
798	    const names = entry.env.map((name) => {
799	      if (typeof name !== 'string' || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
800	        throw new ValidationError('cache entry env must be an array of variable names');
801	      }
802	      return name;
803	    });
804	    if (new Set(names).size !== names.length) {
805	      throw new ValidationError('cache entry env names must be unique');
806	    }
807	    // Copied so the manifest never aliases caller-owned state.
808	    const inputs = inputsValue.map((input) => ({ ...input }));
809	    const env = { names: [...names].sort(), values: {} };
810	    const recomputed = actionKey({ command, inputs, env });
811	    if (recomputed !== normalized) {
812	      throw new ValidationError(
813	        `cache entry does not describe key ${normalized}: the same fields hash to ${recomputed}`,
814	      );
815	    }
816	    const manifestKey = normalized;
817	    if (this.store.hasManifest(manifestKey)) {
818	      throw new ConflictError(`cache entry ${normalized} already exists`);
819	    }
820	    const digest = await this.store.writeBlob(buffer);
821	    // A remote entry carries no resolved dependency keys, so it is only ever
822	    // reachable as the entry of a root node - exactly the entries a peer can
823	    // hand over without shipping its whole graph.
824	    const manifest = buildManifest({
825	      actionId: entry.action_id ?? 'remote',
826	      key: normalized,
827	      command,
828	      inputs,
829	      env,
830	      dependencies: [],
831	      digest,
832	      size: buffer.length,
833	    });
834	    await this.store.writeManifest(manifestKey, manifest);
835	    this.bump('remote_writes');
836	    this.bump('cache_writes');
837	    await this.persistStats();
838	    return manifest;
839	  }
840	
841	  async remoteRead(key) {
842	    await this.loading;
843	    const entry = await this.cacheGet(key);
844	    this.bump('remote_reads');
845	    await this.persistStats();
846	    return entry;
847	  }
848	
849	  async cacheEntries(limit = 500) {
850	    await this.loading;
851	    return this.store.listKeys(limit);
852	  }
853	
854	  // --------------------------------------------------------------------- gc
855	
856	  // Cache retention. The keep set is the node keys of every registered graph's
857	  // last run plus whatever the caller asked to keep; a graph that never ran
858	  // contributes nothing. Every manifest is scanned and validated first, so a
859	  // corrupt store fails the whole request before a single object is deleted.
860	  // Everything outside the keep set is collected: the manifests, the blobs only
861	  // they referenced, and orphan blobs. A dry run reports the exact same sets
862	  // and byte counts without deleting anything.
863	  async gc(request = {}) {
864	    await this.loading;
865	    if (!isPlainObject(request)) throw new ValidationError('gc request must be a JSON object');
866	    rejectUnknown(request, ['keep', 'dry_run'], 'gc request');
867	    const dryRun = request.dry_run === undefined ? false : request.dry_run;
868	    if (typeof dryRun !== 'boolean') throw new ValidationError('gc dry_run must be a boolean');
869	    const keepRequested = new Set();
870	    if (request.keep !== undefined) {
871	      if (!Array.isArray(request.keep)) throw new ValidationError('gc keep must be an array of cache keys');
872	      for (const key of request.keep) keepRequested.add(assertCacheKey(key));
873	    }
874	
875	    const keep = new Set(keepRequested);
876	    for (const run of this.runs.values()) {
877	      for (const node of run.nodes) keep.add(node.key);
878	    }
879	
880	    // Validate before anything is deleted: an unreadable manifest, a key
881	    // mismatch, a missing or dishonest digest, or a missing or tampered blob
882	    // fails the request and leaves the store untouched.
883	    const keys = await this.store.listKeys(Number.MAX_SAFE_INTEGER);
884	    const manifests = new Map();
885	    for (const key of keys) {
886	      const manifest = await this.store.readManifest(key);
887	      const digest = assertDigest(manifest.digest, `cache manifest for key ${key} digest`);
888	      const hexDigest = digest.slice('sha256:'.length);
889	      let buffer;
890	      try {
891	        buffer = await readFile(this.store.blobPath(hexDigest));
892	      } catch (error) {
893	        if (error.code === 'ENOENT') {
894	          throw new ValidationError(
895	            `cache manifest for key ${key} references a blob that is missing from the object store`,
896	          );
897	        }
898	        throw error;
899	      }
900	      if (digestOf(buffer) !== digest) {
901	        throw new ValidationError(`blob referenced by cache manifest for key ${key} does not match its digest`);
902	      }
903	      manifests.set(key, hexDigest);
904	    }
905	
906	    for (const key of keepRequested) {
907	      if (!manifests.has(key)) throw new NotFoundError(`keep key ${key} does not name a cache entry`);
908	    }
909	
910	    const keptKeys = keys.filter((key) => keep.has(key));
911	    const removedKeys = keys.filter((key) => !keep.has(key));
912	    const keptDigests = new Set(keptKeys.map((key) => manifests.get(key)));
913	
914	    const blobSizes = new Map();
915	    for (const hexDigest of await this.store.listBlobDigests()) {
916	      blobSizes.set(hexDigest, (await stat(this.store.blobPath(hexDigest))).size);
917	    }
918	    let keptBytes = 0;
919	    for (const hexDigest of keptDigests) keptBytes += blobSizes.get(hexDigest);
920	    const removedDigests = [...blobSizes.keys()].filter((hexDigest) => !keptDigests.has(hexDigest));
921	    let removedBytes = 0;
922	    for (const hexDigest of removedDigests) removedBytes += blobSizes.get(hexDigest);
923	
924	    if (!dryRun) {
925	      for (const key of removedKeys) await this.store.deleteManifest(key);
926	      for (const hexDigest of removedDigests) await this.store.deleteBlob(hexDigest);
927	    }
928	
929	    return {
930	      dry_run: dryRun,
931	      kept_keys: keptKeys,
932	      removed_keys: removedKeys,
933	      removed_digests: removedDigests.map((hexDigest) => `sha256:${hexDigest}`),
934	      kept_bytes: keptBytes,
935	      removed_bytes: removedBytes,
936	    };
937	  }
938	
939	  // ----------------------------------------------------------- idempotency
940	
941	  async recall(operation, idempotencyKey) {
942	    await this.loading;
943	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return null;
944	    if (idempotencyKey.length > 255) {
945	      throw new ValidationError('Idempotency-Key must be at most 255 characters');
946	    }
947	    const record = await this.store.readMeta(
948	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
949	    );
950	    return record ? { status: record.status, body: record.body } : null;
951	  }
952	
953	  async remember(operation, idempotencyKey, response) {
954	    await this.loading;
955	    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) return;
956	    await this.store.writeMeta(
957	      `idempotency/${sha256Text(`${operation}\n${idempotencyKey}`)}.json`,
958	      {
959	        schema: 'cachelattice/idempotency/v1',
960	        operation,
961	        status: response.status,
962	        body: response.body,
963	      },
964	    );
965	  }
966	
967	  // A cache entry is valid for a node when the manifest's hashed fields still
968	  // describe the action the node runs: same command, same input digests, same
969	  // environment variable names. The action_id is provenance only - two
970	  // differently named actions with the same definition legitimately share one
971	  // entry, and the first one to run wins the label.
972	  assertManifestMatches(manifest, action, key) {
973	    if (manifest.key !== key) {
974	      throw new ConflictError(`cache entry ${key} claims to belong to ${manifest.key}`);
975	    }
976	    const shape = (command, inputs, envNames) =>
977	      canonicalJson({ command, inputs, env_names: envNames });
978	    if (
979	      shape(manifest.command, manifest.inputs, manifest.env.names) !==
980	      shape(action.command, action.inputs, action.env.names)
981	    ) {
982	      throw new ConflictError(`cache entry for ${key} was produced from different inputs`);
983	    }
984	  }
985	}
986	
987	export async function readWorkspaceFile(workspace, relative) {
988	  const absolute = path.join(workspace, relative);
989	  if (absolute !== workspace && !absolute.startsWith(workspace + path.sep)) {
990	    throw new ValidationError(`path escapes the workspace: ${relative}`);
991	  }
992	  let info;
993	  try {
994	    info = await stat(absolute);
995	  } catch (error) {
996	    if (error.code === 'ENOENT') throw new ValidationError(`input file does not exist: ${relative}`);
997	    throw error;
998	  }
999	  if (!info.isFile()) throw new ValidationError(`input path is not a regular file: ${relative}`);
1000	  return readFile(absolute);
1001	}
