1	import { readFile } from 'node:fs/promises';
2	import path from 'node:path';
3	
4	import { canonicalJson } from './canonical.js';
5	import { ExecutionError, ValidationError } from './errors.js';
6	import { normalizePath } from './key.js';
7	
8	// Every command is a pure function of bytes that are already addressed by the
9	// action key. That is the whole reason a cache hit and a cache miss can be
10	// guaranteed to emit the same artifact: the miss path recomputes the same
11	// function from the same bytes, and the hit path reuses the bytes the miss path
12	// stored.
13	export const COMMAND_KINDS = [
14	  'copy-file',
15	  'write-file',
16	  'concat-text',
17	  'substitute-text',
18	  'filter-lines',
19	  'template-hash',
20	];
21	
22	export function normalizeCommand(command) {
23	  const kind = command.kind;
24	  if (!COMMAND_KINDS.includes(kind)) {
25	    throw new ValidationError(`command kind must be one of ${COMMAND_KINDS.join(', ')}`);
26	  }
27	  const normalized = { kind };
28	  if (kind === 'copy-file') {
29	    normalized.source = String(command.source);
30	  } else if (kind === 'write-file') {
31	    normalized.content = String(command.content);
32	  } else if (kind === 'concat-text') {
33	    assertArray(command.sources, 'command sources');
34	    normalized.sources = command.sources.map((value) => String(value));
35	    normalized.separator = typeof command.separator === 'string' ? command.separator : '\n';
36	  } else if (kind === 'substitute-text') {
37	    normalized.source = String(command.source);
38	    assertArray(command.replacements, 'command replacements');
39	    if (command.replacements.length === 0) {
40	      throw new ValidationError('command replacements must not be empty');
41	    }
42	    normalized.replacements = command.replacements
43	      .map((replacement) => {
44	        if (typeof replacement.find !== 'string' || replacement.find.length === 0) {
45	          throw new ValidationError('replacement find must be a non-empty string');
46	        }
47	        if (typeof replacement.replace !== 'string') {
48	          throw new ValidationError('replacement replace must be a string');
49	        }
50	        return { find: replacement.find, replace: replacement.replace };
51	      })
52	      // Sorted so that the order in which replacements were declared cannot
53	      // change the key, and so that "aa"->"b" then "b"->"c" is always applied
54	      // in the same sequence.
55	      .sort((left, right) => (left.find < right.find ? -1 : left.find > right.find ? 1 : 0));
56	  } else if (kind === 'filter-lines') {
57	    normalized.source = String(command.source);
58	    if (typeof command.pattern !== 'string') {
59	      throw new ValidationError('command pattern must be a string');
60	    }
61	    try {
62	      new RegExp(command.pattern);
63	    } catch (error) {
64	      throw new ValidationError(`command pattern is not a valid regular expression: ${error.message}`);
65	    }
66	    normalized.pattern = command.pattern;
67	    normalized.match = command.match === 'drop' ? 'drop' : 'keep';
68	    normalized.keep_final_newline = command.keep_final_newline !== false;
69	  } else if (kind === 'template-hash') {
70	    assertArray(command.fields, 'command fields');
71	    const fields = command.fields.map((field) => {
72	      if (typeof field !== 'string' || field.length === 0) {
73	        throw new ValidationError('command fields must be non-empty strings');
74	      }
75	      return field;
76	    });
77	    const unique = [...new Set(fields)].sort();
78	    if (unique.length !== fields.length) {
79	      throw new ValidationError('command fields must be unique');
80	    }
81	    normalized.fields = unique;
82	  }
83	  // Every workspace path inside a command is normalized here, with the same
84	  // rules as action inputs, so that "./src/a.txt" and "src/a.txt" can never be
85	  // two different keys for the same read.
86	  if ('source' in normalized) {
87	    normalized.source = normalizePath(normalized.source, 'command source');
88	  }
89	  if (normalized.kind === 'concat-text') {
90	    normalized.sources = normalized.sources.map((value) => normalizePath(value, 'command source'));
91	  }
92	  return normalized;
93	}
94	
95	function assertArray(value, label) {
96	  if (!Array.isArray(value)) throw new ValidationError(`${label} must be an array`);
97	}
98	
99	function utf8(text) {
100	  if (typeof text !== 'string') {
101	    throw new ExecutionError('prepared input is not UTF-8 decodable text');
102	  }
103	  return text;
104	}
105	
106	// Workspace-relative source references inside a command. They are normalized
107	// with the same rules as action inputs so that a command and the input list can
108	// never disagree about what "a/../b.txt" names.
109	export function commandSources(command) {
110	  if (command.kind === 'copy-file' || command.kind === 'substitute-text' || command.kind === 'filter-lines') {
111	    return [command.source];
112	  }
113	  if (command.kind === 'concat-text') return [...command.sources];
114	  return [];
115	}
116	
117	export async function executeArtifact({ command: requested, inputs, env, dependencies, workspace }) {
118	  // The executor is the authority on command semantics: it normalizes whatever
119	  // it is handed, so a caller that skipped normalization still gets the same
120	  // bytes as one that did not.
121	  const command = normalizeCommand(requested);
122	  const local = new Map(inputs.map((input) => [input.path, input]));
123	  const readSource = async (relative) => {
124	    const localInput = local.get(relative);
125	    if (localInput && localInput.kind === 'hash') {
126	      throw new ExecutionError(
127	        `command reads ${relative} as a file but the action declares it as a precomputed hash`,
128	      );
129	    }
130	    const absolute = path.join(workspace, relative);
131	    if (absolute !== workspace && !absolute.startsWith(workspace + path.sep)) {
132	      throw new ExecutionError(`path escapes the workspace: ${relative}`);
133	    }
134	    try {
135	      return await readFile(absolute);
136	    } catch (error) {
137	      if (error.code === 'ENOENT') {
138	        throw new ExecutionError(`input file is missing from the workspace: ${relative}`);
139	      }
140	      if (error.code === 'EISDIR') {
141	        throw new ExecutionError(`input path is a directory: ${relative}`);
142	      }
143	      throw error;
144	    }
145	  };
146	
147	  if (command.kind === 'copy-file') {
148	    return readSource(command.source);
149	  }
150	  if (command.kind === 'write-file') {
151	    return Buffer.from(command.content, 'utf8');
152	  }
153	  if (command.kind === 'concat-text') {
154	    const pieces = [];
155	    for (const source of command.sources) pieces.push(utf8((await readSource(source)).toString('utf8')));
156	    return Buffer.from(pieces.join(command.separator), 'utf8');
157	  }
158	  if (command.kind === 'substitute-text') {
159	    let text = utf8((await readSource(command.source)).toString('utf8'));
160	    for (const replacement of command.replacements) {
161	      text = text.split(replacement.find).join(replacement.replace);
162	    }
163	    return Buffer.from(text, 'utf8');
164	  }
