1	import { createHash } from 'node:crypto';
2	import { ValidationError } from './errors.js';
3	
4	// Renders a JSON value with object keys sorted by code unit and no insignificant
5	// whitespace. Two values have the same canonical form if and only if they carry
6	// the same information in the same order, which is what makes every hash in this
7	// repository reproducible across runs and processes.
8	export function canonicalJson(value) {
9	  return render(value, new Set());
10	}
11	
12	function render(value, seen) {
13	  if (value === null) return 'null';
14	  if (typeof value === 'boolean') return value ? 'true' : 'false';
15	  if (typeof value === 'string') return JSON.stringify(value);
16	  if (typeof value === 'number') {
17	    if (!Number.isFinite(value)) {
18	      throw new ValidationError('numbers in hashed content must be finite');
19	    }
20	    return JSON.stringify(value);
21	  }
22	  if (Array.isArray(value)) {
23	    if (seen.has(value)) throw new ValidationError('hashed content must not contain cycles');
24	    seen.add(value);
25	    const body = value.map((item) => render(item, seen));
26	    seen.delete(value);
27	    return `[${body.join(',')}]`;
28	  }
29	  if (typeof value === 'object') {
30	    if (seen.has(value)) throw new ValidationError('hashed content must not contain cycles');
31	    seen.add(value);
32	    const keys = Object.keys(value).sort();
33	    const body = keys.map((key) => `${JSON.stringify(key)}:${render(value[key], seen)}`);
34	    seen.delete(value);
35	    return `{${body.join(',')}}`;
36	  }
37	  throw new ValidationError(`hashed content must not contain ${typeof value}`);
38	}
39	
40	// Encoding form of a hash: "<algorithm>:<lowercase hex>".
41	export function sha256Bytes(buffer) {
42	  return createHash('sha256').update(buffer).digest('hex');
43	}
44	
45	export function sha256Text(text) {
46	  return sha256Bytes(Buffer.from(text, 'utf8'));
47	}
48	
49	export function digestOf(buffer) {
50	  return `sha256:${sha256Bytes(buffer)}`;
51	}
52	
