    try {
      const entry = await this.store.readArtifact(node.key);
      cached.set(node.id, { digest: node.digest, buffer: entry.buffer });
    } catch (error) {
      issues.push({ id: node.id, issue: 'cache_unreadable', detail: error.message });
    }
